// Generated by scripts/gen_swift_cypher.py from health_graph/{schema,omop}.cypher,
// store.py and queries.py. Do not edit: change the Python and run the script.
// The parity test (CypherParityTests) fails if the two drift apart.
// swiftlint:disable line_length

enum Cypher {
  static let schema = #"""
  // Local Sovereign Health Graph: schema (Relate / openCypher)
  // Keys follow the EHDS Hub's *code* (ui/src/lib/patient/app-observations.ts,
  // scripts/load_fhir_neo4j.py), not the design spec, so `relate push` merges cleanly.
  // Run once per store; every statement is idempotent.

  // ── L3 FHIR ──────────────────────────────────────────────────────────────────
  CREATE CONSTRAINT patient_id IF NOT EXISTS FOR (n:Patient) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT observation_resource_id IF NOT EXISTS FOR (n:Observation) REQUIRE n.resourceId IS UNIQUE;
  CREATE CONSTRAINT diagnostic_report_resource_id IF NOT EXISTS FOR (n:DiagnosticReport) REQUIRE n.resourceId IS UNIQUE;
  CREATE CONSTRAINT document_reference_resource_id IF NOT EXISTS FOR (n:DocumentReference) REQUIRE n.resourceId IS UNIQUE;
  CREATE CONSTRAINT provenance_resource_id IF NOT EXISTS FOR (n:Provenance) REQUIRE n.resourceId IS UNIQUE;
  CREATE CONSTRAINT organization_name IF NOT EXISTS FOR (n:Organization) REQUIRE n.name IS UNIQUE;
  CREATE INDEX observation_source_report IF NOT EXISTS FOR (n:Observation) ON (n.sourceReport);
  CREATE INDEX observation_effective_date IF NOT EXISTS FOR (n:Observation) ON (n.effectiveDate);

  // ── L4 OMOP ──────────────────────────────────────────────────────────────────
  CREATE CONSTRAINT omop_person_id IF NOT EXISTS FOR (n:OMOPPerson) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT omop_measurement_id IF NOT EXISTS FOR (n:OMOPMeasurement) REQUIRE n.id IS UNIQUE;

  // ── L5 Ontology ──────────────────────────────────────────────────────────────
  CREATE CONSTRAINT loinc_code IF NOT EXISTS FOR (n:LoincCode) REQUIRE n.code IS UNIQUE;
  CREATE CONSTRAINT ncbi_taxon_code IF NOT EXISTS FOR (n:NcbiTaxon) REQUIRE n.code IS UNIQUE;

  // ── Search ───────────────────────────────────────────────────────────────────
  // Find values by the words on the paper report (German labels) or the LOINC name.
  CREATE FULLTEXT INDEX observation_text IF NOT EXISTS FOR (n:Observation) ON EACH [n.display, n.sourceLine];
  CREATE FULLTEXT INDEX loinc_text IF NOT EXISTS FOR (n:LoincCode) ON EACH [n.display];

  // ── Knowledge layer (health_graph/knowledge.py) ─────────────────────────────
  // Health risks, the scores that estimate them, the measures they use, and the
  // guideline and optimal ranges from Klarbefund's reference-ranges.ts.
  CREATE CONSTRAINT health_risk_id IF NOT EXISTS FOR (n:HealthRisk) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT risk_score_id IF NOT EXISTS FOR (n:RiskScore) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT reference_range_id IF NOT EXISTS FOR (n:ReferenceRange) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT score_result_id IF NOT EXISTS FOR (n:ScoreResult) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT knowledge_id IF NOT EXISTS FOR (n:Knowledge) REQUIRE n.id IS UNIQUE;
  CREATE CONSTRAINT study_id IF NOT EXISTS FOR (n:Study) REQUIRE n.id IS UNIQUE;
  """#

  static let omop = #"""
  // Local FHIR -> OMOP CDM v5.4 transform, ported from the EHDS Hub's
  // neo4j/fhir-to-omop-transform.cypher (plain MERGE/SET, no APOC).
  // Difference: reads the app's property names (valueQuantity, effectiveDate),
  // which the Hub transform currently misses (it reads value / dateTime).
  // Concept ids stay 0: Athena is not on the device; LOINC goes into measurementSourceValue.

  // 1. OMOPPerson: year of birth only, never names (Hub #475)
  MATCH (p:Patient)
  MERGE (op:OMOPPerson {id: 'omop-person-' + p.id})
  SET op.personSourceValue = p.id,
      op.yearOfBirth = p.birthYear,
      op.genderConceptId = CASE p.gender WHEN 'male' THEN 8507 WHEN 'female' THEN 8532 ELSE 0 END
  MERGE (p)-[:MAPPED_TO]->(op)
  RETURN count(op) AS omop_persons;

  // 2. OMOPMeasurement from numeric laboratory / vital-sign Observations
  MATCH (p:Patient)-[:HAS_OBSERVATION]->(o:Observation)
  WHERE o.category IN ['laboratory', 'vital-signs'] AND o.valueQuantity IS NOT NULL AND o.code IS NOT NULL
    AND o.duplicateOf IS NULL
  MATCH (p)-[:MAPPED_TO]->(op:OMOPPerson)
  MERGE (om:OMOPMeasurement {id: 'omop-meas-' + o.resourceId})
  SET om.measurementDate = left(o.effectiveDate, 10),
      om.measurementSourceValue = o.code,
      om.measurementConceptId = 0,
      om.valueAsNumber = o.valueQuantity,
      om.operatorSourceValue = o.comparator,
      om.unitSourceValue = o.unit,
      om.rangeLow = o.referenceLow,
      om.rangeHigh = o.referenceHigh,
      om.measurementTypeSourceValue = o.sourceKind
  MERGE (o)-[:MAPPED_TO]->(om)
  MERGE (op)-[:HAS_MEASUREMENT]->(om)
  RETURN count(om) AS omop_measurements;

  // 2b. A copy of a value another report already carries (Observation.duplicateOf,
  // see store.py) is not a second measurement
  MATCH (o:Observation)-[:MAPPED_TO]->(om:OMOPMeasurement)
  WHERE o.duplicateOf IS NOT NULL
  DETACH DELETE om
  RETURN count(*) AS omop_duplicates_removed;

  // 3. Vocabulary bridge OMOPMeasurement -> LoincCode
  MATCH (o:Observation)-[:CODED_BY]->(lc:LoincCode)
  MATCH (o)-[:MAPPED_TO]->(om:OMOPMeasurement)
  MERGE (om)-[:CODED_BY]->(lc)
  RETURN count(*) AS omop_coded;
  """#

  static let deleteReport = #"""
  MATCH (o:Observation {sourceReport: $reportId})
  OPTIONAL MATCH (o)-[:MAPPED_TO]->(om:OMOPMeasurement)
  DETACH DELETE om, o
  """#

  static let upsertReport = #"""
  MERGE (p:Patient {id: $patientId})
  SET p += $patient
  MERGE (dr:DiagnosticReport {resourceId: $report.resourceId})
  SET dr += $report
  MERGE (p)-[:HAS_DIAGNOSTIC_REPORT]->(dr)
  WITH p, dr
  CALL (dr) {
    WITH dr WHERE $report.performer IS NOT NULL
    MERGE (org:Organization {name: $report.performer})
    MERGE (dr)-[:PERFORMED_BY]->(org)
  }
  CALL (dr) {
    WITH dr WHERE $document IS NOT NULL
    MERGE (doc:DocumentReference {resourceId: $document.resourceId})
    SET doc += $document
    MERGE (dr)-[:DERIVED_FROM]->(doc)
  }
  CALL (dr) {
    WITH dr WHERE $provenance IS NOT NULL
    MERGE (pv:Provenance {resourceId: $provenance.resourceId})
    SET pv += $provenance
    MERGE (pv)-[:TARGET]->(dr)
  }
  RETURN dr.resourceId AS report
  """#

  static let upsertObservations = #"""
  MATCH (p:Patient {id: $patientId})
  MATCH (dr:DiagnosticReport {resourceId: $reportResourceId})
  UNWIND $rows AS r
  MERGE (o:Observation {resourceId: r.resourceId})
  SET o += r, o.sourceReport = $reportId, o.contributedBy = 'klarbefund-app'
  MERGE (p)-[:HAS_OBSERVATION]->(o)
  MERGE (dr)-[:HAS_RESULT]->(o)
  WITH o, r
  CALL (o, r) {
    WITH o, r WHERE r.code IS NOT NULL
    MERGE (lc:LoincCode {code: r.code})
    ON CREATE SET lc.display = r.loincDisplay
    MERGE (o)-[:CODED_BY]->(lc)
  }
  CALL (o, r) {
    WITH o, r WHERE r.taxonCode IS NOT NULL
    MERGE (t:NcbiTaxon {code: r.taxonCode})
    ON CREATE SET t.display = r.taxonDisplay
    MERGE (o)-[:IDENTIFIES]->(t)
  }
  RETURN count(o) AS stored
  """#

  static let unlinkSameMeasurements = #"""
  MATCH (o:Observation) WHERE o.duplicateOf IS NOT NULL
  OPTIONAL MATCH (o)-[s:SAME_AS]->()
  DELETE s
  REMOVE o.duplicateOf
  RETURN count(DISTINCT o) AS cleared
  """#

  static let linkSameMeasurements = #"""
  MATCH (o:Observation)
  WHERE coalesce(o.sourceKind, '') <> 'device-weekly-mean'
    AND o.valueQuantity IS NOT NULL AND o.effectiveDate IS NOT NULL
  WITH o, coalesce(o.code, 'label:' + toLower(trim(o.display))) AS measure,
       CASE o.sourceKind WHEN 'lab-issued-digital' THEN 0 WHEN 'ocr-transcribed' THEN 1 ELSE 2 END AS rank
  ORDER BY rank, o.resourceId
  WITH measure, left(o.effectiveDate, 10) AS day, o.valueQuantity AS value,
       coalesce(o.comparator, '') AS comparator, coalesce(o.unit, '') AS unit, collect(o) AS same
  WHERE size(same) > 1
  WITH head(same) AS kept, tail(same) AS copies
  UNWIND copies AS copy
  SET copy.duplicateOf = kept.resourceId
  MERGE (copy)-[:SAME_AS]->(kept)
  RETURN count(copy) AS duplicates
  """#

  static let replaceWearables = #"""
  MERGE (p:Patient {id: $patientId})
  WITH p
  OPTIONAL MATCH (p)-[:HAS_OBSERVATION]->(old:Observation {sourceReport: $source})
  OPTIONAL MATCH (old)-[:MAPPED_TO]->(om:OMOPMeasurement)
  DETACH DELETE om, old
  """#

  static let upsertWearables = #"""
  MATCH (p:Patient {id: $patientId})
  UNWIND $rows AS r
  MERGE (o:Observation {resourceId: r.resourceId})
  SET o += r, o.sourceReport = $source, o.contributedBy = 'klarbefund-app'
  MERGE (p)-[:HAS_OBSERVATION]->(o)
  MERGE (lc:LoincCode {code: r.code})
  ON CREATE SET lc.display = r.loincDisplay
  MERGE (o)-[:CODED_BY]->(lc)
  RETURN count(o) AS stored
  """#

  static let seedRisks = #"""
  UNWIND $risks AS r
  MERGE (h:HealthRisk {id: r.id})
  SET h.name = r.name, h.description = r.description
  RETURN count(h) AS risks
  """#

  static let seedScores = #"""
  UNWIND $scores AS s
  MERGE (rs:RiskScore {id: s.id})
  SET rs.name = s.name, rs.unit = s.unit, rs.source = s.source, rs.demographics = s.demographics
  WITH rs, s
  MATCH (h:HealthRisk {id: s.estimates})
  MERGE (rs)-[:ESTIMATES]->(h)
  WITH rs, s
  UNWIND s.uses AS code
  MERGE (lc:LoincCode {code: code})
  MERGE (rs)-[:USES]->(lc)
  RETURN count(DISTINCT rs) AS scores
  """#

  static let seedMarkers = #"""
  UNWIND $markers AS m
  MATCH (h:HealthRisk {id: m.risk})
  MERGE (lc:LoincCode {code: m.loinc})
  MERGE (lc)-[k:MARKER_OF]->(h)
  SET k.source = m.source
  RETURN count(k) AS markers
  """#

  static let seedPruneRanges = #"""
  MATCH (rr:ReferenceRange)
  WHERE NOT rr.id IN $rangeIds
  DETACH DELETE rr
  RETURN count(*) AS prunedRanges
  """#

  static let seedRanges = #"""
  UNWIND $ranges AS r
  MERGE (rr:ReferenceRange {id: r.id})
  SET rr += r
  WITH rr, r
  MERGE (lc:LoincCode {code: r.loinc})
  MERGE (rr)-[:APPLIES_TO]->(lc)
  RETURN count(rr) AS ranges
  """#

  static let seedRangeSources = #"""
  UNWIND $rangeSources AS s
  MERGE (st:Study {id: s.id})
  SET st.citation = s.citation, st.title = s.title, st.year = s.year, st.design = s.design, st.url = s.url,
      st.pmid = s.pmid, st.pubmedUrl = s.pubmedUrl, st.kind = s.kind, st.topics = s.topics
  WITH st, s
  UNWIND s.ranges AS rid
  MATCH (rr:ReferenceRange {id: rid})
  MERGE (rr)-[:SOURCED_FROM]->(st)
  RETURN count(DISTINCT st) AS rangeSources
  """#

  static let seedStudies = #"""
  UNWIND $studies AS s
  MERGE (st:Study {id: s.id})
  SET st.citation = s.citation, st.title = s.title, st.year = s.year, st.design = s.design, st.url = s.url,
      st.pmid = s.pmid, st.pubmedUrl = s.pubmedUrl, st.kind = s.kind, st.topics = s.topics
  RETURN count(st) AS studies
  """#

  static let seedStudyCitations = #"""
  UNWIND $citations AS c
  MATCH (a:Study {id: c.from})
  MATCH (b:Study {id: c.to})
  MERGE (a)-[k:CITES]->(b)
  SET k.source = 'OpenAlex referenced_works'
  RETURN count(k) AS citations
  """#

  static let seedStudyMarkers = #"""
  UNWIND $examines AS e
  MATCH (st:Study {id: e.study})
  MERGE (lc:LoincCode {code: e.code})
  SET lc.display = coalesce(lc.display, e.name)
  MERGE (st)-[k:EXAMINES]->(lc)
  RETURN count(k) AS studyMarkers
  """#

  static let seedStudyScores = #"""
  UNWIND $informs AS i
  MATCH (st:Study {id: i.study})
  MATCH (rs:RiskScore {id: i.score})
  MERGE (st)-[k:INFORMS]->(rs)
  RETURN count(k) AS studyScores
  """#

  static let seedRiskLinks = #"""
  UNWIND $links AS l
  MATCH (a:HealthRisk {id: l.from})
  MATCH (b:HealthRisk {id: l.to})
  MERGE (a)-[k:RAISES_RISK_OF]->(b)
  SET k.summary = l.summary, k.measure = l.measure, k.estimate = l.estimate,
      k.ciLow = l.ciLow, k.ciHigh = l.ciHigh, k.studies = l.studies
  WITH a, b, k, l
  UNWIND l.studies AS sid
  MATCH (st:Study {id: sid})
  MERGE (st)-[:ABOUT]->(a)
  MERGE (st)-[:ABOUT]->(b)
  RETURN count(DISTINCT k) AS riskLinks
  """#

  static let seedVersion = #"""
  MERGE (k:Knowledge {id: 'health-graph'})
  SET k.fingerprint = $fingerprint, k.rangesSource = $rangesSource
  RETURN k.fingerprint AS fingerprint
  """#
}

/// Named read-only queries (CLI, tests, the app). Same as health_graph/queries.py.
public enum Queries {
  public static let all: [String: (description: String, cypher: String)] = [
    "reports": (
      "All imported reports with lab, source and how many values the Hub would accept",
      #"""
      MATCH (p:Patient)-[:HAS_DIAGNOSTIC_REPORT]->(dr:DiagnosticReport)-[:HAS_RESULT]->(o:Observation)
      OPTIONAL MATCH (dr)-[:DERIVED_FROM]->(doc:DocumentReference)
      RETURN dr.effectiveDate AS date, dr.performer AS lab, doc.title AS document,
             collect(DISTINCT o.sourceKind)[0] AS source, count(o) AS values,
             sum(CASE WHEN o.hubEligible THEN 1 ELSE 0 END) AS hubReady,
             sum(CASE WHEN o.duplicateOf IS NOT NULL THEN 1 ELSE 0 END) AS alsoInAnotherReport
      ORDER BY date
      """#),
    "trend": (
      "Trend of one analyte (param loinc) across all reports, with provenance; each measurement once",
      #"""
      MATCH (:Patient)-[:HAS_OBSERVATION]->(o:Observation)-[:CODED_BY]->(lc:LoincCode {code: $loinc})
      WHERE o.duplicateOf IS NULL
      OPTIONAL MATCH (dr:DiagnosticReport)-[:HAS_RESULT]->(o)
      OPTIONAL MATCH (copy:Observation)-[:SAME_AS]->(o)
      RETURN left(o.effectiveDate, 10) AS date, o.display AS label,
             coalesce(o.comparator, '') + toString(o.valueQuantity) AS value, o.unit AS unit,
             o.referenceText AS printedRange, o.sourceKind AS source,
             o.verifiedByPatientAt IS NOT NULL AS verified,
             coalesce(dr.performer, o.performer) AS lab, count(copy) AS alsoInOtherReports
      ORDER BY date
      """#),
    "wearables": (
      "Apple Health weekly means (resting HR, HRV, steps, weight) sent by Klarbefund",
      #"""
      MATCH (:Patient)-[:HAS_OBSERVATION]->(o:Observation {sourceReport: 'apple-health-weekly'})
      RETURN o.display AS metric, o.effectiveStart AS weekStart, o.valueQuantity AS mean,
             o.unit AS unit, o.performer AS devices
      ORDER BY metric, weekStart
      """#),
    "analytes": (
      "Every coded analyte with how often and when it was measured (copies counted once)",
      #"""
      MATCH (o:Observation)-[:CODED_BY]->(lc:LoincCode)
      WHERE o.duplicateOf IS NULL
      RETURN lc.code AS loinc, lc.display AS name, count(o) AS n,
             min(o.effectiveDate) AS first, max(o.effectiveDate) AS last
      ORDER BY n DESC, loinc
      """#),
    "unmapped": (
      "Values without a LOINC code, and the reason (honesty about data quality)",
      #"""
      MATCH (o:Observation) WHERE o.code IS NULL
      OPTIONAL MATCH (o)-[:IDENTIFIES]->(t:NcbiTaxon)
      RETURN o.display AS label, o.effectiveDate AS date, t.code AS ncbiTaxon,
             o.unmappedReason AS reason
      ORDER BY date
      """#),
    "duplicates": (
      "Values that appear in more than one report: the copy kept, and where else it was found",
      #"""
      MATCH (copy:Observation)-[:SAME_AS]->(kept:Observation)
      OPTIONAL MATCH (kr:DiagnosticReport)-[:HAS_RESULT]->(kept)
      OPTIONAL MATCH (cr:DiagnosticReport)-[:HAS_RESULT]->(copy)
      RETURN left(kept.effectiveDate, 10) AS date, kept.display AS label,
             coalesce(kr.title, kr.performer) AS keptIn, kept.sourceKind AS keptSource,
             coalesce(cr.title, cr.performer) AS copyIn, copy.sourceKind AS copySource
      ORDER BY date, label
      """#),
    "scores": (
      "Risk scores stored for the person, with the values each one used (python -m health_graph scores)",
      #"""
      MATCH (:Patient)-[:HAS_SCORE]->(sr:ScoreResult)-[:OF]->(rs:RiskScore)-[:ESTIMATES]->(h:HealthRisk)
      OPTIONAL MATCH (sr)-[:FROM]->(o:Observation)
      RETURN rs.name AS score, h.name AS risk, sr.value AS value, sr.unit AS unit, sr.band AS band,
             sr.light AS light, sr.demographics AS demographics, left(sr.computedAt, 10) AS computed,
             collect(o.display + ' ' + toString(o.valueQuantity) + ' ' + coalesce(o.unit, '')
                     + ' (' + left(o.effectiveDate, 10) + ')') AS inputs, rs.source AS source
      ORDER BY score
      """#),
    "ranges": (
      "Guideline range and optimal band for one LOINC code (param loinc), with the source",
      #"""
      MATCH (rr:ReferenceRange)-[:APPLIES_TO]->(:LoincCode {code: $loinc})
      RETURN rr.analyteKey AS analyte, rr.ucum AS unit, rr.sex AS sex,
             rr.guidelineLow AS guidelineLow, rr.guidelineHigh AS guidelineHigh,
             rr.optimalLow AS optimalLow, rr.optimalHigh AS optimalHigh,
             rr.summary AS summary, rr.sourceLabel AS source
      ORDER BY unit, sex
      """#),
    "risk": (
      "One health risk (param risk: cardiovascular, diabetes, kidney, liver, bone, fitness): its scores and markers",
      #"""
      MATCH (h:HealthRisk {id: $risk})
      OPTIONAL MATCH (rs:RiskScore)-[:ESTIMATES]->(h)
      OPTIONAL MATCH (m:LoincCode)-[k:MARKER_OF]->(h)
      OPTIONAL MATCH (:Patient)-[:HAS_OBSERVATION]->(o:Observation)-[:CODED_BY]->(m)
      WHERE o.duplicateOf IS NULL
      WITH h, rs, m, k, o ORDER BY o.effectiveDate DESC
      WITH h, rs, m, k, collect(o)[0] AS last
      RETURN h.name AS risk, collect(DISTINCT rs.name) AS scores, m.code AS loinc, m.display AS measure,
             last.valueQuantity AS latest, last.unit AS unit, left(last.effectiveDate, 10) AS date,
             k.source AS source
      ORDER BY date DESC
      """#),
    "risk_links": (
      "How the health risks raise each other, with the effect size and the studies that show it",
      #"""
      MATCH (a:HealthRisk)-[k:RAISES_RISK_OF]->(b:HealthRisk)
      OPTIONAL MATCH (st:Study)-[:ABOUT]->(a)
      WHERE st.id IN k.studies
      RETURN a.name AS risk, b.name AS raisesRiskOf, k.measure AS measure, k.estimate AS estimate,
             k.ciLow AS ciLow, k.ciHigh AS ciHigh, k.summary AS summary,
             collect(st.citation) AS studies
      ORDER BY risk, raisesRiskOf
      """#),
    "evidence": (
      "The studies about one marker (param loinc): what they found, with DOI and PubMed links",
      #"""
      MATCH (st:Study)-[:EXAMINES]->(:LoincCode {code: $loinc})
      OPTIONAL MATCH (st)-[:INFORMS]->(rs:RiskScore)
      OPTIONAL MATCH (a:HealthRisk)-[k:RAISES_RISK_OF]->(b:HealthRisk)
      WHERE st.id IN k.studies
      RETURN st.citation AS study, st.year AS year, st.design AS design,
             collect(DISTINCT rs.name) AS scores,
             collect(DISTINCT a.name + ' -> ' + b.name) AS riskLinks,
             st.url AS doi, st.pubmedUrl AS pubmed
      ORDER BY year DESC
      """#),
    "provenance": (
      "Where one value (param resourceId) came from: line on the paper, OCR, document, agent",
      #"""
      MATCH (o:Observation {resourceId: $resourceId})<-[:HAS_RESULT]-(dr:DiagnosticReport)
      OPTIONAL MATCH (dr)-[:DERIVED_FROM]->(doc:DocumentReference)
      OPTIONAL MATCH (pv:Provenance)-[:TARGET]->(dr)
      RETURN o.display AS label, o.valueQuantity AS value, o.unit AS unit,
             o.sourceKind AS source, o.sourceLine AS line, o.ocrConfidence AS ocr,
             o.originalReading AS correctedFrom, o.verifiedByPatientAt AS verifiedAt,
             doc.title AS document, pv.activity AS activity, pv.agent AS agent
      """#),
    "search": (
      "Full-text search (param q) over printed labels, source lines and LOINC names",
      #"""
      CALL () {
        MATCH (o:Observation)
        SEARCH o IN (FULLTEXT INDEX observation_text FOR $q LIMIT 20) SCORE AS score
        RETURN o, score
        UNION
        MATCH (lc:LoincCode)
        SEARCH lc IN (FULLTEXT INDEX loinc_text FOR $q LIMIT 20) SCORE AS score
        MATCH (o:Observation)-[:CODED_BY]->(lc)
        RETURN o, score
      }
      RETURN o.display AS label, o.code AS loinc, o.effectiveDate AS date,
             o.valueQuantity AS value, o.unit AS unit, max(score) AS score
      ORDER BY score DESC, date
      """#),
    "omop": (
      "OMOP CDM measurements (concept id 0, LOINC as source value)",
      #"""
      MATCH (op:OMOPPerson)-[:HAS_MEASUREMENT]->(om:OMOPMeasurement)
      RETURN om.measurementDate AS date, om.measurementSourceValue AS loinc,
             om.valueAsNumber AS value, om.unitSourceValue AS unit,
             om.measurementConceptId AS conceptId
      ORDER BY date, loinc
      """#),
    "stats": (
      "Node counts per label",
      #"""
      MATCH (n) RETURN labels(n)[0] AS label, count(*) AS n ORDER BY label
      """#),
  ]
}
